module robot_movement (\n    input wire clk,\n    input wire rst_n,\n    input wire start,\n    input wire [63:0] grid_data,\n    input wire [31:0] program,\n    input wire [5:0] start_pos,\n    input wire [3:0] prog_len,\n    output reg done,\n    output reg [15:0] result\n);\n\n    // State encoding\n    localparam [2:0] IDLE = 3'd0;\n    localparam [2:0] INIT = 3'd1;\n    localparam [2:0] SIMULATE = 3'd2;\n    localparam [2:0] CHECK_CYCLE = 3'd3;\n    localparam [2:0] DONE_STATE = 3'd4;\n    \n    reg [2:0] state;\n    reg [2:0] next_state;\n    \n    // Current simulation state\n    reg [2:0] cur_row;\n    reg [2:0] cur_col;\n    reg [2:0] prog_idx;\n    reg [15:0] step_count;\n    \n    // Visited states bitmap\n    reg [511:0] visited_states;\n    \n    // Next state logic\n    always @(*) begin\n        next_state = state;\n        case (state)\n            IDLE: if (start) next_state = INIT;\n            INIT: next_state = SIMULATE;\n            SIMULATE: begin\n                if (step_count >= 16'd512) next_state = DONE_STATE;\n                else if (visited_states[{cur_row, cur_col, prog_idx}]) next_state = CHECK_CYCLE;\n                else next_state = SIMULATE;\n            end\n            CHECK_CYCLE: next_state = DONE_STATE;\n            DONE_STATE: next_state = IDLE;\n            default: next_state = IDLE;\n        endcase\n    end\n\n    // State transition\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) state <= IDLE;\n        else state <= next_state;\n    end\n\n    integer i;\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            cur_row <= 3'd0;\n            cur_col <= 3'd0;\n            prog_idx <= 3'd0;\n            step_count <= 16'd0;\n            visited_states <= 512'd0;\n            done <= 1'b0;\n            result <= 16'd0;\n        end else begin\n            case (state)\n                INIT: begin\n                    cur_row <= start_pos[5:3];\n                    cur_col <= start_pos[2:0];\n                    prog_idx <= 3'd0;\n                    step_count <= 16'd1;\n                    visited_states <= 512'd0;\n                    visited_states[{start_pos[5:3], start_pos[2:0], 3'd0}] <= 1'b1;\n                    done <= 1'b0;\n                end\n                \n                SIMULATE: begin\n                    if (!visited_states[{cur_row, cur_col, prog_idx}]) begin\n                        visited_states[{cur_row, cur_col, prog_idx}] <= 1'b1;\n                        case (prog_idx)\n                            3'd0: _process_command(program[3:0]);\n                            3'd1: _process_command(program[7:4]);\n                            3'd2: _process_command(program[11:8]);\n                            3'd3: _process_command(program[15:12]);\n                            3'd4: _process_command(program[19:16]);\n                            3'd5: _process_command(program[23:20]);\n                            3'd6: _process_command(program[27:24]);\n                            3'd7: _process_command(program[31:28]);\n                        endcase\n                        \n                        if (prog_idx == prog_len - 1'b1) prog_idx <= 3'd0;\n                        else prog_idx <= prog_idx + 3'd1;\n                    end\n                end\n                \n                CHECK_CYCLE: begin\n                    result <= step_count;\n                    done <= 1'b1;\n                end\n                \n                DONE_STATE: begin\n                    if (state == SIMULATE) result <= 16'd1;\n                    done <= 1'b1;\n                end\n                        \n                IDLE: begin\n                    done <= 1'b0;\n                    result <= 16'd0;\n                end\n            endcase\n        end\n    end\n    \n    task _process_command(input [3:0] cmd);\n        begin\n            case (cmd)\n                4'd0: begin // <\n                    if ((cur_col > 3'd0) && grid_data[{cur_row, cur_col-3'd1}]) begin\n                        cur_col <= cur_col - 3'd1;\n                        step_count <= step_count + 16'd1;\n                    end\n                end\n                4'd1: begin // >\n                    if ((cur_col < 3'd7) && grid_data[{cur_row, cur_col+3'd1}]) begin\n                        cur_col <= cur_col + 3'd1;\n                        step_count <= step_count + 16'd1;\n                    end\n                end\n                4'd2: begin // ^\n                    if ((cur_row > 3'd0) && grid_data[{cur_row-3'd1, cur_col}]) begin\n                        cur_row <= cur_row - 3'd1;\n                        step_count <= step_count + 16'd1;\n                    end\n                end\n                4'd3: begin // v\n                    if ((cur_row < 3'd7) && grid_data[{cur_row+3'd1, cur_col}]) begin\n                        cur_row <= cur_row + 3'd1;\n                        step_count <= step_count + 16'd1;\n                    end\n                end\n            endcase\n        end\n    endtask\n    \nendmodule